func (o *debian) dpkgPs() error {
	stdout, err := o.ps()
	if err != nil {
		return xerrors.Errorf("Failed to ps: %w", err)
	}
	pidNames := o.parsePs(stdout)
	pidLoadedFiles := map[string][]string{}
	// for pid, name := range pidNames {
	for pid := range pidNames {
		stdout := ""
		stdout, err = o.lsProcExe(pid)
		if err != nil {
			o.log.Debugf("Failed to exec /proc/%s/exe err: %s", pid, err)
			continue
		}
		s, err := o.parseLsProcExe(stdout)
		if err != nil {
			o.log.Debugf("Failed to parse /proc/%s/exe: %s", pid, err)
			continue
		}
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], s)

		stdout, err = o.grepProcMap(pid)
		if err != nil {
			o.log.Debugf("Failed to exec /proc/%s/maps: %s", pid, err)
			continue
		}
		ss := o.parseGrepProcMap(stdout)
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], ss...)
	}

	pidListenPorts := map[string][]models.ListenPort{}
	stdout, err = o.lsOfListen()
	if err != nil {
		return xerrors.Errorf("Failed to ls of: %w", err)
	}
	portPids := o.parseLsOf(stdout)
	for port, pids := range portPids {
		for _, pid := range pids {
			pidListenPorts[pid] = append(pidListenPorts[pid], o.parseListenPorts(port))
		}
	}

	for pid, loadedFiles := range pidLoadedFiles {
		o.log.Debugf("dpkg -S %#v", loadedFiles)
		pkgNames, err := o.getPkgName(loadedFiles)
		if err != nil {
			o.log.Debugf("Failed to get package name by file path: %s, err: %s", pkgNames, err)
			continue
		}

		procName := ""
		if _, ok := pidNames[pid]; ok {
			procName = pidNames[pid]
		}
		proc := models.AffectedProcess{
			PID:         pid,
			Name:        procName,
			ListenPorts: pidListenPorts[pid],
		}

		for _, n := range pkgNames {
			p, ok := o.Packages[n]
			if !ok {
				return xerrors.Errorf("pkg not found %s", n)
			}
			p.AffectedProcs = append(p.AffectedProcs, proc)
			o.Packages[p.Name] = p
		}
	}
	return nil
}

func (o *debian) getPkgName(paths []string) (pkgNames []string, err error) {
	cmd := "dpkg -S " + strings.Join(paths, " ")
	pidLoadedFiles := map[string][]string{}
	for pid := range pidNames {
		stdout := ""
		stdout, err = o.lsProcExe(pid)
		if err != nil {
			o.log.Debugf("Failed to exec /proc/%s/exe err: %s", pid, err)
			continue
		}
		s, err := o.parseLsProcExe(stdout)
		if err != nil {
			o.log.Debugf("Failed to parse /proc/%s/exe: %s", pid, err)
			continue
		}
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], s)

		stdout, err = o.grepProcMap(pid)
		if err != nil {
			o.log.Debugf("Failed to exec /proc/%s/maps: %s", pid, err)
			continue
		}
		ss := o.parseGrepProcMap(stdout)
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], ss...)
	}

	pidListenPorts := map[string][]models.ListenPort{}
	stdout, err = o.lsOfListen()
	if err != nil {
		return xerrors.Errorf("Failed to ls of: %w", err)
	}
	portPids := o.parseLsOf(stdout)
	for port, pids := range portPids {
		for _, pid := range pids {
			pidListenPorts[pid] = append(pidListenPorts[pid], o.parseListenPorts(port))
		}
	}

	for pid, loadedFiles := range pidLoadedFiles {
		o.log.Debugf("rpm -qf: %#v", loadedFiles)
		pkgNames, err := o.getPkgName(loadedFiles)
		if err != nil {
			o.log.Debugf("Failed to get package name by file path: %s, err: %s", pkgNames, err)
			continue
		}

		uniq := map[string]struct{}{}
		for _, name := range pkgNames {
			uniq[name] = struct{}{}
		}

		procName := ""
		if _, ok := pidNames[pid]; ok {
			procName = pidNames[pid]
		}
		proc := models.AffectedProcess{
			PID:         pid,
			Name:        procName,
			ListenPorts: pidListenPorts[pid],
		}

		for fqpn := range uniq {
			p, err := o.Packages.FindByFQPN(fqpn)
			if err != nil {
				return err
			}
			p.AffectedProcs = append(p.AffectedProcs, proc)
			o.Packages[p.Name] = *p
		}
	}
	return nil
}

func (o *redhatBase) needsRestarting() error {
	initName, err := o.detectInitSystem()
	if err != nil {
		o.log.Warn(err)
		// continue scanning
	}

	cmd := "LANGUAGE=en_US.UTF-8 needs-restarting"
	r := o.exec(cmd, sudo)
	if !r.isSuccess() {
		indexFormat = "[%1d]"
	} else if len(r.ScannedCves) < 100 {
		indexFormat = "[%2d]"
	} else {
		indexFormat = "[%3d]"
	}

	for i, vinfo := range r.ScannedCves.ToSortedSlice() {
		max := vinfo.MaxCvssScore().Value.Score
		cvssScore := "|     "
		if 0 < max {
			cvssScore = fmt.Sprintf("| %4.1f", max)
		}

		pkgNames := vinfo.AffectedPackages.Names()
		pkgNames = append(pkgNames, vinfo.CpeURIs...)
		pkgNames = append(pkgNames, vinfo.GitHubSecurityAlerts.Names()...)
		pkgNames = append(pkgNames, vinfo.WpPackageFixStats.Names()...)
		pkgNames = append(pkgNames, vinfo.LibraryFixedIns.Names()...)

		av := vinfo.AttackVector()
		for _, pname := range vinfo.AffectedPackages.Names() {
			if r.Packages[pname].HasPortScanSuccessOn() {
				av = fmt.Sprintf("%s ◉", av)
				break
			}
		}

		exploits := ""
		if 0 < len(vinfo.Exploits) || 0 < len(vinfo.Metasploits) {
			exploits = "POC"
		}

		var cols []string
		cols = []string{
			fmt.Sprintf(indexFormat, i+1),
			vinfo.CveID,
			cvssScore + " |",
			fmt.Sprintf("%-6s |", av),
			fmt.Sprintf("%3s |", exploits),
			fmt.Sprintf("%6s |", vinfo.AlertDict.FormatSource()),
			fmt.Sprintf("%7s |", vinfo.PatchStatus(r.Packages)),
			strings.Join(pkgNames, ", "),
		}
		icols := make([]interface{}, len(cols))
		for j := range cols {
			icols[j] = cols[j]
		}
		stable.AddRow(icols...)
	}

	return fmt.Sprintf("%s", stable)
}

func setDetailLayout(g *gocui.Gui) error {
	maxX, maxY := g.Size()

	summaryView, err := g.View("summary")
	if err != nil {
		return err
	}
	_, cy := summaryView.Cursor()
	_, oy := summaryView.Origin()
	currentVinfo = cy + oy

	if v, err := g.SetView("detail", -1, int(float64(maxY)*0.2), int(float64(maxX)*0.5), maxY); err != nil {
		if err != gocui.ErrUnknownView {
			return err
		}
		text, err := detailLines()
		if err != nil {
			return err
		}
		fmt.Fprint(v, text)
		v.Editable = false
		v.Wrap = true

		currentDetailLimitY = len(strings.Split(text, "\n")) - 1
	}
	return nil
}

